cmdline:
pwsh.exe -NoProfile -NoLogo -NonInteractive -Command "try { [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch {}; try { if (Microsoft.PowerShell.Utility\Get-Variable -Name PSStyle -ErrorAction Ignore) { $PSStyle.OutputRendering = 'PlainText' } } catch {}; function Clear-Host {}; $global:LASTEXITCODE = 0; $__copilotCommandFinished = $false; $__copilotSuccess = $false; try { $global:LASTEXITCODE = 0 @' def sub(p, a, b): s=open(p,encoding='utf-8').read(); assert a in s,(p,a); s=s.replace(a,b,1); open(p,'w',encoding='utf-8',newline='
').write(s) sub('public/index.html',"one coach-written next step, never your words; it goes with hints and coach tips","one coach-written next step, which may echo a few of your words; it goes with hints and coach tips") sub('README.md',"one coach-written next step of at most 120 characters, never the learner's words;","one coach-written next step of at most 120 characters, which may echo a few of the learner's words but never four in a row;") sub('docs/privacy-safety.md',"and one short next-step line the coach wrote, never the learner's words)","and one short next-step line the coach wrote, which may echo a few of the learner's words but never four in a row)") sub('public/ui/my-data.js',"one coach-written line; never the learner's words)","one coach-written line, which may echo a few of the learner's words)") sub('e2e/setup.spec.js'," await expect(notice).not.toContainText('no conversation text');"," await expect(notice).not.toContainText('no conversation text');
 await expect(notice).toContainText('one coach-written next step, which may echo a few of your words');
 await expect(notice).not.toContainText('next step, never your words');") '@ | python -; npm run build 2>&1 | Out-Null; for ($i=0; $i -lt 60; $i++) { if (-not (Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | ? { $_.LocalPort -in 3100,3101,3102,3106,3107,3108,3109,3110,3111 })) { break }; Start-Sleep 5 }; npx playwright test e2e/setup.spec.js --reporter=line 2>&1 | Select-String "passed|failed|already used" | Select-Object -Last 2 $__copilotSuccess = $? $__copilotCommandFinished = $true } finally { if ($__copilotCommandFinished) { if (-not $__copilotSuccess -and $LASTEXITCODE -is [int] -and $LASTEXITCODE -ne 0) { $host.SetShouldExit($LASTEXITCODE) } elseif (-not $__copilotSuccess) { $host.SetShouldExit(1) } else { $host.SetShouldExit(0) } } }"
